Gblocks=[['A','H','K','M','S'], ['B','D','J','V','X'], ['C','I','L','U','W'], ['E','G','N','R','Y'], ['F','O','P','Q','T']]
G=[sorted(idx[ch] for ch in block) for block in Gblocks]
Gcanon=tuple(sorted(tuple(b) for b in G))

class UF:
    def __init__(self,n=25):
        self.p=list(range(n)); self.sz=[1]*n
    def find(self,x):
        while self.p[x]!=x:
            self.p[x]=self.p[self.p[x]]; x=self.p[x]
        return x
    def union(self,a,b):
        a=self.find(a); b=self.find(b)
        if a==b: return False
        if self.sz[a]<self.sz[b]: a,b=b,a
        self.p[b]=a; self.sz[a]+=self.sz[b]
        return True
    def groups(self):
        d=collections.defaultdict(list)
        for i in range(25): d[self.find(i)].append(i)
        return tuple(sorted(tuple(v) for v in d.values()))

def congruence_generated(pair):
    uf=UF(25)
    uf.union(*pair)
    changed=True
    while changed:
        changed=False
        # all currently equivalent pairs
        reps=[uf.find(i) for i in range(25)]
        eqpairs=[(x,y) for x in range(25) for y in range(x+1,25) if reps[x]==reps[y]]
        for x,y in eqpairs:
            for a in range(25):
                for b in range(25):
                    if uf.union(t(x,a,b), t(y,a,b)): changed=True
                    if uf.union(t(a,x,b), t(a,y,b)): changed=True
                    if uf.union(t(a,b,x), t(a,b,y)): changed=True
    return uf.groups()

parts=set()
by_sizes=collections.defaultdict(list)
allpairs=[(a,b) for a in range(25) for b in range(a+1,25)]
start=time.time()
for pair in allpairs:
    part=congruence_generated(pair)
    if part not in parts:
        parts.add(part)
        sizes=tuple(sorted(len(b) for b in part))
        by_sizes[sizes].append(part)
        print('new partition from',pair,'sizes',sizes,'blocks',[[letters[i] for i in bl] for bl in part])
print('num unique partitions',len(parts),'elapsed',time.time()-start)
print('size types', {k:len(v) for k,v in by_sizes.items()})
# identify nontrivial 5x5 partitions different from G
