    pair_to_sym[pair]=x
print('pair_to_sym size',len(pair_to_sym))
# quotient rules
qG={}
qH={}
for a,b,c in itertools.product(range(25), repeat=3):
    kg=(Gcls[a],Gcls[b],Gcls[c]); vg=Gcls[t(a,b,c)]
    kh=(Hcls[a],Hcls[b],Hcls[c]); vh=Hcls[t(a,b,c)]
    if kg in qG and qG[kg]!=vg: print('qG not well-defined'); raise SystemExit
    if kh in qH and qH[kh]!=vh: print('qH not well-defined'); raise SystemExit
    qG[kg]=vg; qH[kh]=vh
print('qG,qH sizes',len(qG),len(qH))
# start states
